.board th, .board td { padding: 8px 10px; border-bottom: 1px solid var(--line); text-align: left; vertical-align: middle; }
.board thead th { background: var(--gold-soft); font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; }
.board tbody tr { cursor: pointer; }
.board tbody tr:hover { background: var(--accent-soft); }
.board tbody tr.selected { background: var(--sage-soft); }
.board .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.board .name { font-weight: 700; }
.badge {
  display: inline-block;
  background: var(--sage);
  color: #fff;
  border-radius: 4px;
  padding: 1px 6px;
  margin-left: 6px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.05em;
  vertical-align: 2px;
}
.bar { display: inline-block; height: 8px; background: var(--bar); border-radius: 4px; vertical-align: middle; }
.more { color: var(--muted); font-size: 13px; text-align: center; }
footer { margin-top: 26px; color: var(--muted); font-size: 13px; border-top: 1px solid var(--line); padding-top: 14px; }
footer code { background: var(--accent-soft); padding: 0 4px; border-radius: 4px; }
@media (max-width: 720px) {
  .stats { grid-template-columns: repeat(2, 1fr); }
  .factors { grid-template-columns: repeat(2, 1fr); }
  h1 { font-size: 26px; }
}
